import torch

def to_cuda(batch, device="cuda", ignore_list: bool = False) -> torch.Tensor:
    """
    Converts the input batch to a CUDA tensor, recursively handling nested structures like tuples, lists, and dictionaries, 
    except for dictionary keys named "meta". It ensures that the data is moved to the specified CUDA device for GPU processing.

    Input-Output Arguments
    :param batch: tuple, list, dict, torch.Tensor, or other. The input data that needs to be converted to a CUDA tensor. 
                  It supports nested structures and handles them accordingly.
    :param device: str, default "cuda". The target CUDA device to which the data will be moved.
    :param ignore_list: bool, default False. A flag to indicate whether to ignore certain elements, though its usage is not directly apparent in the function's implementation.
    :return: torch.Tensor. The input batch converted to a CUDA tensor, ready for GPU processing.
    """

    # If batch is a tensor, move it to the specified device
    if isinstance(batch, torch.Tensor):
        return batch.to(device)

    # If batch is a list or tuple, recursively process each element
    elif isinstance(batch, (list, tuple)):
        return type(batch)(to_cuda(item, device, ignore_list) for item in batch)

    # If batch is a dictionary, recursively process each value except for "meta"
    elif isinstance(batch, dict):
        return {key: to_cuda(value, device, ignore_list) if key != "meta" else value for key, value in batch.items()}

