        return easyvolcap.utils.base_utils.dotdict({key: to_cuda(value, device, ignore_list) if key != "meta" else value for key, value in batch.items()})

    # If batch is of any other type, try to convert it to a tensor and move it to the specified device
    else:
        try:
            return torch.tensor(batch).to(device)
        except ValueError:
            return batch
